if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !base64 <text>\nPrefix with "decode:" to decode');
const input = argumentName.trim();
try {
  if (input.toLowerCase().startsWith('decode:')) {
    const encoded = input.slice(7).trim();
    const decoded = Buffer.from(encoded, 'base64').toString('utf-8');
    await sendTrackedMessage(sock, remoteJid, `🔓 Decoded:\n${decoded}`);
  } else {
    const encoded = Buffer.from(input).toString('base64');
    await sendTrackedMessage(sock, remoteJid, `🔒 Encoded:\n${encoded}`);
  }
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Invalid input for encoding/decoding.');
}
